import {cardsView,cardResults,defaultCardFilters} from './pilot-cards.js?v=38';
import {buildRatingCards,ratingBreakdownText,ratingPolicy} from './analiz/overall.js?v=36';
import {ratingReviews} from './analiz/rating-data.js?v=42';
import {analysisInfo} from './analiz/promotion-info.js?v=42';
import {performanceRows,performanceTotals,raceMetrics} from './performance.js?v=44';
import {rules} from './rules-data.js?v=23';
import {L,currentRound,team,pilot,gp,licence,standings,teamStandings,movement,stats,expiryBatches,raceRows,sanction,driverCases,teamMembers,activePilots,hasSprint,countdownState,currentAffiliation,dpCleared} from './logic.js?v=44';
const $=s=>document.querySelector(s),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes=[['home','Lig merkezi'],['standings','Puan durumu'],['statistics','İstatistikler'],['decisions','FIA kararları'],['licence','Ceza puanları'],['races','Yarışlar'],['teams','Takımlar'],['pilot-cards','Pilot Kartları'],['news','Paddock haberleri'],['rules','Kural kitapçığı']];
let countdownTimer;
let ruleQuery='';
let statsRound='all',statsSession='Yarış',statsPilot='all';
let route='home',value='',champ='drivers',raceSession='Yarış',decisionPilot='all',decisionRound='all',decisionType='all',driverSearch='',teamFilter='all',onlyCompleted=false;
const href=(r,v)=>r==='analysis'?'analiz/'+(v?'#'+encodeURIComponent(v):''):'#'+r+(v?'/'+encodeURIComponent(v):'');
const link=(r,text,cls='',v='')=>`<a class="${cls}" href="${href(r,v)}">${text}</a>`;
const logo=t=>`<img class="team-logo" src="${h(team(t).logo)}" alt="${h(t)} logosu" loading="lazy">`;
const flag=r=>`<img class="flag" src="${h(gp(r)?.flag)}" alt="${h(gp(r)?.name)} bayrağı" loading="lazy">`;
const avatar=p=>p?.portrait?`<img class="portrait" src="${h(p.portrait)}" alt="${h(p.name)} için temsilî ${h(p.representative)}" loading="lazy">`:`<span class="initials">${h(p?.name.split(' ').map(x=>x[0]).slice(0,2).join('')||'?')}</span>`;
const teamLabel=t=>`<span class="team-label" style="--team:${team(t).color}"><i></i>${h(t)}</span>`;
const affiliationLogo=p=>{const a=currentAffiliation(p);return `<img class="team-logo ${a.kind==='departed'?'departure-logo':''}" src="${h(a.logo)}" alt="${a.kind==='departed'?h(a.name)+' simgesi':h(a.name)+' logosu'}" loading="lazy">`;};
const affiliationLabel=p=>p.active===false?`<span class="departure-label">${h(currentAffiliation(p).name.toLocaleUpperCase('tr'))} <span>· Aktif takımı yok</span></span>`:teamLabel(p.team);
const move=(name,kind='drivers')=>{const m=movement(name,kind);return m?`<span class="movement ${m>0?'up':'down'}" aria-label="${Math.abs(m)} sıra ${m>0?'yükseldi':'geriledi'}">${m>0?'▲':'▼'} ${Math.abs(m)}</span>`:'<span class="movement steady" aria-label="Sırası değişmedi">—</span>'};
function heading(eyebrow,title,desc,aside=''){return `<section class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${desc}</p></div>${aside}</section>`;}
function driverLink(name){const p=pilot(name);return p?link('pilot',h(name),'driver-name',p.id):h(name);}
const select=(id,label,options,v)=>`<label class="select-field"><span>${label}</span><select id="${id}">${options.map(([val,name])=>`<option value="${h(val)}" ${String(val)===String(v)?'selected':''}>${h(name)}</option>`).join('')}</select></label>`;
const ratingCards=buildRatingCards(L.pilots,ratingReviews,currentRound);
const cardContext={
 h,team,select,
 roster:L.pilots.filter(p=>p.active!==false).map(pilot=>({pilot,rating:ratingCards.find(row=>row.pilotId===pilot.id)})),
 latestReview:ratingReviews.filter(review=>review.round<=currentRound).at(-1)
};
let cardFilters={...defaultCardFilters};
function cardsPage(){return cardsView(cardContext,cardFilters);}
function refreshCardResults(){
 const {count,markup}=cardResults(cardContext,cardFilters);
 $('#card-count').textContent=count;
 $('#card-results').innerHTML=markup;
}
function resetCardFilters(){
 cardFilters={...defaultCardFilters};
 $('#card-search').value=cardFilters.search;
 $('#card-team').value=cardFilters.team;
 $('#card-order').value=cardFilters.order;
 refreshCardResults();
 $('#card-search').focus();
}
function pageShell(){
 const active=route==='pilot'||route==='team'?'teams':route==='race'?'races':route;
 const brand=`<a class="brand" href="#home" aria-label="FPL ana sayfa"><strong>FPL</strong><span>PADDOCK<br>LEAGUE</span></a>`;
 $('#header').innerHTML=`<div class="header-inner">${brand}<nav class="desktop-nav" aria-label="Ana menü">${routes.map(([r,t])=>`<a href="${href(r)}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${t}</a>`).join('')}</nav><a class="header-card-route ${active==='pilot-cards'?'active':''}" href="${href('pilot-cards')}" ${active==='pilot-cards'?'aria-current="page"':''}>Pilot Kartları</a><a class="header-analysis" href="analiz/" aria-label="Yarış merkezi — yeni"><span class="header-analysis-new">YENİ</span><span>Yarış merkezi</span><span class="header-analysis-icon" aria-hidden="true">${navIcon('analysis')}</span></a><button class="menu-toggle" data-menu-open aria-label="Menüyü aç" aria-expanded="false" aria-controls="mobile-menu">${navIcon('menu')}<span>Menü</span></button></div>`;
 $('#mobile-navigation').innerHTML=`<div class="mobile-menu-backdrop" data-menu-close hidden></div><section id="mobile-menu" class="mobile-menu" role="dialog" aria-modal="true" aria-labelledby="mobile-menu-title" tabindex="-1" hidden><div class="mobile-menu-head">${brand}<button data-menu-close class="menu-close" aria-label="Menüyü kapat">${navIcon('close')}</button></div><div class="mobile-menu-body"><p class="eyebrow">FPL 2026 · PADDOCK LEAGUE</p><h2 id="mobile-menu-title">Tüm paddock.<br><em>Tek dokunuşla.</em></h2><nav class="mobile-menu-links" aria-label="Tüm sayfalar">${routes.map(([r,t],i)=>`<a href="${href(r)}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}><span class="mobile-link-icon">${navIcon(r)}</span><span>${t}</span><small>${String(i+1).padStart(2,'0')}</small><b aria-hidden="true">↗</b></a>`).join('')}</nav><p class="mobile-menu-note"><span class="live-dot"></span>22 Grand Prix. Tek şampiyonluk.</p></div></section><nav class="mobile-tab-bar" aria-label="Hızlı gezinme">${[['home','Lig merkezi'],['standings','Puanlar'],['races','Yarışlar'],['teams','Takımlar'],['pilot-cards','Kartlar']].map(([r,t])=>`<a href="${href(r)}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}>${navIcon(r)}<span>${t}</span></a>`).join('')}<button data-menu-open aria-label="Tüm sayfalar menüsünü aç" aria-controls="mobile-menu" aria-expanded="false">${navIcon('menu')}<span>Menü</span></button></nav>`;
 $('#footer').innerHTML=`<div class="footer-inner"><a href="#home" class="footer-brand">FPL <span>PADDOCK LEAGUE</span></a><p>Sportif adalet. Temiz yarış. Eşit rekabet.</p><button data-about>Lig bilgisi & görsel kaynakları ↗</button></div><div class="footer-fine">${h(L.asOf)} · ${L.currentRound} GP + ${new Set(L.results.filter(r=>r.session==='Sprint').map(r=>r.round)).size} sprint · Bilgiler lig yönetiminin paylaştığı kayıtlardan hazırlanmıştır.</div>`;
}
function standingTable(limit=activePilots().length){const rows=standings().slice(0,limit),lead=rows[0].points;return `<div class="table-scroll"><table class="standings-table"><thead><tr><th>SIRA</th><th>PİLOT / TAKIM</th><th class="hide-small">SON GP</th><th class="hide-small">FARK</th><th>PUAN</th></tr></thead><tbody>${rows.map(p=>`<tr class="${p.active===false?'departed-row':''}"><td><span class="rank ${p.rank<=3?'rank-'+p.rank:''}">${String(p.rank).padStart(2,'0')}</span>${move(p.name)}</td><td><div class="driver-cell">${affiliationLogo(p)}<div>${driverLink(p.name)}${affiliationLabel(p)}</div></div></td><td class="hide-small">${raceRows(currentRound).find(r=>r.name===p.name)?.points??'—'}</td><td class="hide-small muted">${lead-p.points===0?'LİDER':'−'+(lead-p.points)}</td><td><strong class="table-points">${p.points}</strong></td></tr>`).join('')}</tbody></table></div>`;}
function applicationState(p){return ['provisional','scheduled'].includes(p.applicationStatus)&&p.type!=='Grid'?'pending':p.applicationStatus==='onHold'?'hold':p.applicationStatus==='served'?'served':p.applicationStatus==='pending'?'pending':p.type==='Grid'?'grid':'applied';}
const dpText=p=>p.points==null?(p.dpStatus==='not_specified'?'EK DP BELİRTİLMEDİ':'DP BEKLENİYOR'):dpCleared(p)?'DP SİLİNDİ':`+${p.points} DP`;
function applicationLabel(p){if(p.type==='Uyarı')return '✓ DİSİPLİN KAYDINA İŞLENDİ';if(p.type==='İşlem yok')return '✓ İNCELEME KAPATILDI';if(p.resultStatus==='DSQ'&&p.applicationStatus==='recorded')return 'RESMÎ KLASMAN · DSQ';if(p.type==='Men'&&p.applicationStatus!=='served')return '↘ '+(gp(p.applies)?.name||'SONRAKİ GP').toLocaleUpperCase('tr')+' · YARIŞTAN MEN';if(p.applicationStatus==='provisional')return '◷ GEÇİCİ KLASMANA İŞLENDİ';return p.decisionStatus==='pending'?'◷ YAPTIRIM / DP BEKLENİYOR':p.applicationStatus==='onHold'?'◷ ÇEKİLMEDİ · TAKIMSIZ PİLOT':p.type==='DP kaydı'?'✓ EK DP KAYDINA İŞLENDİ':p.applicationStatus==='served'?(p.serviceEvidenceSource==='recording_result'?'✓ ÇEKİLDİ · MADRİD P11 / 11':'✓ ÇEKİLDİ · '+(gp(p.servedRound)?.name||'LİG YÖNETİMİ ONAYI').toLocaleUpperCase('tr')):p.type==='Grid'?'↘ SONRAKİ GRAND PRIX · SONDAN BAŞLAMA':p.round===9&&p.type==='Saniye'&&p.applicationStatus==='applied'?'✓ KLASMANA İŞLENDİ · SIRA DEĞİŞMEDİ':p.applicationStatus==='pending'?`◷ ${p.resultStatus||'DNF'} · UYGULAMA KARARI BEKLENİYOR`:'✓ SONUCA UYGULANDI';}
function penaltyCard(p){const state=applicationState(p);return `<article class="decision-card application-${state}" style="--team:${team(p.team).color}"><div class="card-overline"><span>${flag(p.round)} ${p.type==='DP kaydı'?'EK DP KAYDI · R'+String(p.round).padStart(2,'0'):h(p.gp)+(p.session==='Sprint'?' Sprint':' GP')+(p.decisionNumber==null?' · GRİD BİLDİRİMİ':' · KARAR '+String(p.decisionNumber).padStart(2,'0'))}</span></div><div class="decision-driver">${logo(p.team)}<div>${driverLink(p.name)}${teamLabel(p.team)}</div><span class="sanction">${h(sanction(p))}</span></div>${p.lap||p.trackPart?`<span class="decision-lap">${p.lap?p.lap+'. TUR':''}${p.lap&&p.trackPart?' · ':''}${h(p.trackPart||'')}</span>`:''}<span class="application-pill ${state}">${applicationLabel(p)}</span><p class="decision-reason">${h(p.reason)}</p>${p.relatedPilots?.length?`<p class="decision-related">İlgili pilotlar: ${p.relatedPilots.map(driverLink).join(' · ')}</p>`:p.affectedDriverCount?`<p class="decision-related">İlgili pilot sayısı: ${p.affectedDriverCount} · İsimler paylaşılmadı.</p>`:''}${p.type==='Grid'&&p.gridPolicy!=='FPL-R09-BACK'?`<p class="grid-card-note">Önceki karar: +${p.originalSeconds} sn → ${p.amount} sıra grid · ${p.applicationStatus==='onHold'?'Takımsız · Uygulama beklemede':p.applicationStatus==='served'?'Çekildi olarak kapatıldı':'Sonraki katılacağı Grand Prix'}</p>`:''}${p.type==='Grid'&&p.nonServiceDP&&!dpCleared(p)?`<p class="grid-card-note">Mevcut ${p.points} DP + çekilmeyen grid için ${p.nonServiceDP} ek DP · Ayrı R${String(p.nonServiceReviewRound).padStart(2,'0')} kaydı</p>`:''}<div class="decision-bottom"><span class="dp-chip ${dpCleared(p)?'cleared':''}">${dpText(p)}</span><span class="muted small">${p.rules.map(x=>'Md. '+x).join(' · ')}</span><button class="text-button" data-case="${h(p.id)}">Kararı oku ↗</button></div></article>`;}
function home(){const leader=standings()[0],last=gp(currentRound),next=gp(currentRound+1),top=raceRows(currentRound).slice(0,3);return `<section class="hero"><div class="hero-grid"></div><div class="hero-copy"><p class="eyebrow">FPL PADDOCK LEAGUE · 2026</p><h1>YARIŞ BİTER.<br><em>HİKÂYE DEVAM EDER.</em></h1><p class="hero-sub">${h(last.name)} GP sonrası sıradaki durak ${h(next.name)}. Puan durumu, güncel kadrolar ve pistin ardından alınan kararlar. Tüm paddock tek yerde.</p><div class="hero-actions">${link('race',h(last.name)+' sonuçları <span>↗</span>','button primary',String(currentRound))}${link('standings','Şampiyonaya bak →','button secondary')}${link('pilot-cards','Pilot kartları','button secondary')}</div><div class="hero-meta"><span><b>${activePilots().length}</b> AKTİF PİLOT</span><span><b>${L.teams.length}</b> TAKIM</span><span><b>${String(currentRound).padStart(2,'0')} / 22</b> GRAND PRIX</span></div></div><div class="hero-art"><span class="giant-round">${String(currentRound).padStart(2,'0')}</span><img class="hero-car" src="${team(top[0].team).car}" alt="${h(top[0].team)} 2026 yarış aracı"><div class="hero-winner"><span class="live-dot"></span><div><small>${last.classificationStatus==='provisional'?'GEÇİCİ KLASMAN LİDERİ':'SON YARIŞIN KAZANANI'}</small><strong>${h(top[0].name)}</strong><span>${flag(last.round)} ${h(last.name)} GP · ${h(top[0].team)}</span></div><span class="winner-mark">P1</span></div></div></section>${countdownBanner()}${scheduleNotice()}<section class="season-strip"><div><span class="eyebrow">ŞAMPİYONA LİDERİ</span><b>${h(leader.name)} <em>${leader.points} PUAN</em></b></div><div><span class="eyebrow">SON YARIŞ</span><b>${flag(last.round)} ${h(last.name)} <small>R${last.round} tamamlandı</small></b></div><div><span class="eyebrow">SIRADAKİ DURAK</span><b>${flag(next.round)} ${h(next.name)} <small>${next.sprintStatus==='unconfirmed'?'Sprint bilgisi bekleniyor':hasSprint(next.round)?'Sprint hafta sonu':'Grand Prix'}</small></b></div></section><section class="home-grid"><div><div class="section-heading"><div><p class="eyebrow">HER PUANIN BİR HİKÂYESİ VAR</p><h2>Şampiyonluk yarışı</h2></div>${link('standings','Tüm sıralama ↗','text-button')}</div><section class="panel">${standingTable(5)}</section></div><div><div class="section-heading"><div><p class="eyebrow">${h(last.name).toLocaleUpperCase('tr')} GP</p><h2>Son podyum</h2></div>${link('race','Sonuçlar ↗','text-button',String(last.round))}</div><div class="podium-mini">${[top[1],top[0],top[2]].map(r=>`<a href="${href('pilot',pilot(r.name).id)}" class="podium-person place-${r.position}" style="--team:${team(r.team).color}"><div class="podium-face">${avatar(pilot(r.name))}</div><strong>${h(r.name)}</strong><span>${logo(r.team)}${h(r.team)}</span><div class="podium-step"><b>${r.position}</b><small>${r.points} PUAN</small></div></a>`).join('')}</div></div></section><section><div class="section-heading"><div><p class="eyebrow">PADDOCK’TAN SON GELİŞMELER</p><h2>Yeni renkler. Yeni hikâyeler.</h2></div>${link('news','Tüm haberler ↗','text-button')}</div><div class="news-grid">${L.news.slice(0,3).map(newsCard).join('')}</div></section><section><div class="section-heading"><div><p class="eyebrow">${h(gp(driverCases()[0]?.round)?.name||last.name)} GP · HAKEM KURULU</p><h2>Son FIA kararları</h2></div>${link('decisions','Tüm kararlar ↗','text-button')}</div>${pendingBanner()}<div class="decision-grid">${driverCases().slice(0,3).map(penaltyCard).join('')}</div></section><section class="licence-promo"><div><p class="eyebrow">SÜRÜCÜ LİSANSI</p><h2>Puanın kaç?<br><span>Ne zaman silinecek?</span></h2><p>Yeni kitapçığa göre ceza puanları 10 yarış boyunca geçerli. Miami DP’leri R16 Brezilya, Kanada DP’leri R17 Meksika GP sonrası silinecek.</p>${link('licence','Ceza puanlarını incele ↗','button primary')}</div><div class="promo-score"><strong>10</strong><span>YARIŞLIK<br>GEÇERLİLİK</span></div></section>`;}
function standingsPage(){return heading('2026 SEZONU · ROUND '+String(currentRound).padStart(2,'0')+' SONRASI','ŞAMPİYONLUK YARIŞI.',L.asOf+' puan durumu. Her yarış, yeni bir hikâye.')+`<div class="tab-row" role="group" aria-label="Şampiyona seçimi"><button class="${champ==='drivers'?'selected':''}" data-champ="drivers">Pilotlar şampiyonası</button><button class="${champ==='teams'?'selected':''}" data-champ="teams">Takımlar şampiyonası</button></div>`+(champ==='drivers'?`<section class="panel">${standingTable()}</section>`:`<section class="constructor-list" aria-label="Takımlar sıralaması">${teamStandings().map(t=>`<a class="constructor-row" href="${href('team',t.name)}" style="--team:${t.color}"><div class="constructor-rank"><b>${String(t.rank).padStart(2,'0')}</b>${move(t.name,'teams')}</div><div class="constructor-identity">${logo(t.name)}<div><h2>${h(t.name)}</h2><span>${teamMembers(t.name).map(p=>h(p.name)).join(' · ')||'Aktif kadro açıklanmadı'}</span></div></div><img class="constructor-row-car" src="${t.car}" alt="${h(t.name)} 2026 aracı" loading="lazy"><div class="constructor-points"><b>${t.points}</b><small>PUAN</small></div><span class="constructor-arrow" aria-hidden="true">↗</span></a>`).join('')}</section>`)+`<p class="data-note">Tabloda yalnız aktif pilotlar yer alır. Ayrılanların kazanılmış puanları korunur. Oklar aynı aktif pilotlar arasında ${h(gp(currentRound-1).name)} GP sonrası sıralamaya göre değişimi gösterir. Utku’nun puanları R08’den itibaren sıfırdan hesaplanır. Takım puanları yarıştaki takıma yazılır; transferle taşınmaz.</p>`;}
function decisionsPage(){const list=driverCases().filter(p=>(decisionPilot==='all'||p.name===decisionPilot)&&(decisionRound==='all'||p.round===Number(decisionRound))&&(decisionType==='all'||(decisionType==='pending'?['pending','scheduled','onHold'].includes(p.applicationStatus):decisionType==='applied'?p.applicationStatus==='applied':decisionType==='served'?p.applicationStatus==='served':p.type===decisionType)));return heading('FPL · FIA KARARLARI','PİSTTE NE OLDU?','Kararlar, bekleyen incelemeler ve yaptırımların uygulanma durumu. Yeni disiplin dönemi Miami GP ile başladı.')+`<div class="reset-notice">${h(L.discipline.resetNotice)}</div>${L.discipline.updateNotice?`<div class="discipline-update">${h(L.discipline.updateNotice)}</div>`:''}<div class="status-legend"><span class="application-pill applied">✓ Uygulandı</span><span class="application-pill pending">◷ Uygulama bekliyor</span><span class="application-pill grid">↘ Kesinleşmiş grid cezası</span><span class="application-pill served">✓ Çekildi · Kapatıldı</span><span class="application-pill hold">◷ Takımsız · Beklemede</span></div>${pendingBanner()}<div class="filters">${select('decisionPilot','Pilot',[['all','Tüm pilotlar'],...L.pilots.filter(p=>p.active!==false||driverCases(p.name).length).map(p=>[p.name,p.name])],decisionPilot)}${select('decisionRound','Grand Prix',[['all','Tüm yarışlar'],...L.races.filter(r=>L.penalties.some(p=>p.round===r.round)).map(r=>[r.round,r.name+' GP'])],decisionRound)}${select('decisionType','Durum / yaptırım',[['all','Tüm kararlar'],['applied','Sonuca uygulandı'],['served','Çekildi / kapatıldı'],['pending','Henüz uygulanmayan cezalar'],['Grid','Kesinleşmiş grid cezası'],['Men','Yarıştan men'],['Uyarı','Uyarı'],['İşlem yok','İşlem yapılmadı'],['DP kaydı','Ek DP kayıtları']],decisionType)}<span class="filter-count">${list.length} karar</span><button class="text-button" data-reset>Filtreleri sıfırla</button></div><div class="decision-grid">${list.map(penaltyCard).join('')||'<div class="empty">Bu filtreye uygun karar bulunmuyor.</div>'}</div><p class="data-note">Kesin sonuçlara uygulanmış süreler ikinci kez eklenmez. DNF veya DSQ nedeniyle uygulanamayan süreler sonraki yarışa otomatik saniye veya belirli bir grid sıra sayısı olarak çevrilmez. Kesinleşmiş grid kararları mor, uygulama kararı bekleyen kayıtlar amber, çekilmiş cezalar yeşil gösterilir. Bu durumlar DP’nin silinmesi anlamına gelmez.</p>`;}
function licencePage(){
 const roster=activePilots().filter(p=>p.team);
 const rows=roster.map(p=>({...p,...licence(p.name)})).sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name,'tr'));
 const batches=expiryBatches(currentRound,new Set(roster.map(p=>p.name)));return heading('FPL · SÜRÜCÜ LİSANSI','CEZA PUANLARI.','Puanlar ve silinme takvimi, güncel takım kadrolarındaki pilotları kapsar.',`<span class="outline-tag">R${String(currentRound).padStart(2,'0')} SONRASI</span>`)+`<div class="licence-summary"><div><b>${rows.reduce((n,r)=>n+r.points,0)}</b><span>AKTİF CEZA PUANI</span></div><div><b>${rows.filter(r=>r.points>0).length}</b><span>PUANLI PİLOT</span></div><div><b>${rows.filter(r=>r.points>=6).length}</b><span>DİSİPLİN TAKİBİNDE</span></div><div><b>${batches[0]?'R'+batches[0].round:'—'}</b><span>İLK PUAN SİLİNMESİ</span></div></div><div class="licence-layout"><section class="panel licence-board"><div class="board-head"><span>PİLOT / GÜNCEL TAKIM</span><span>AKTİF DP</span><span>İLK SİLİNME</span></div>${rows.map((p,i)=>`<details class="licence-row ${p.points>=6?'warning':''}"><summary><div class="driver-cell"><span class="ordinal">${String(i+1).padStart(2,'0')}</span>${affiliationLogo(p)}<div><b>${h(p.name)}</b>${affiliationLabel(p)}</div></div><div class="licence-number"><b>${p.points}</b><small>${p.status}</small></div><div class="next-expiry">${p.next?`<b>${h(p.next.expiresGP)} GP</b><span>${p.remaining} yarış sonra <i>⌄</i></span>`:'<span>Aktif puan yok <i>⌄</i></span>'}</div></summary><div class="licence-expanded">${p.batches.map(b=>`<div class="batch"><div>${flag(b.round)}<span><b>${h(b.gp)} GP</b><small>R${String(b.round).padStart(2,'0')} · Alınan puan</small></span></div><strong>+${b.points} DP</strong><span class="batch-arrow">→</span><div><b>${h(b.expiresGP)} GP sonrası</b><small>R${b.expires} · ${b.expires-currentRound} yarış kaldı</small></div></div>`).join('')||'<p>Bu pilotun kayıtlı aktif ceza puanı yok.</p>'}<a class="text-button" href="${href('pilot',p.id)}">Pilot profili ve tüm cezaları ↗</a></div></details>`).join('')}</section><aside><div class="panel expiry-panel"><p class="eyebrow">SİLİNME TAKVİMİ</p><h2>Hangi yarışta<br>ne silinecek?</h2>${batches.map(b=>`<details class="expiry-event"><summary><span>${flag(b.round)}<b>${h(b.gp)} GP<small>R${b.round} · ${b.round-currentRound} yarış sonra</small></b></span><strong>−${b.points} DP <i>⌄</i></strong></summary><div>${[...b.pilots].map(([n,p])=>`<p>${driverLink(n)}<b>−${p} DP</b></p>`).join('')}</div></details>`).join('')}</div><div class="licence-rule"><h3>10 yarış kuralı</h3><p>Miami (R06) puanları R16 Brezilya, Kanada (R07) puanları R17 Meksika GP tamamlanıp FIA kararları kesinleşince silinir. Grid cezasının çekilmesi DP’yi silmez. Çekilmeyen gridler için R08’de eklenen DP, R18 ABD / COTA sonrası silinir.</p><p>Yalnız süresi dolan puanlar düşer; Miami’den itibaren karar geçmişi korunur. Men cezası tamamlandığında DP sıfırlanır. Miami öncesi kayıtlar lig kararıyla sıfırlandı. Sayfa toplamı güncel takım kadrolarına göre gösterilir.</p><div><span>6 DP · Disiplin takibi</span><span>9 DP · Son uyarı</span><span>12 DP · Sonraki GP’den men</span></div></div></aside></div>`;}
function racesPage(){return heading('FPL 2026 · 22 GRAND PRIX','BİR SEZON. 22 HİKÂYE.','Tamamlanan yarışın üstüne dokun; podyumu, tam sonuçları ve FIA kararlarını keşfet.')+scheduleNotice()+`<div class="tab-row"><button class="${!onlyCompleted?'selected':''}" data-calendar="all">Tüm takvim</button><button class="${onlyCompleted?'selected':''}" data-calendar="done">Tamamlanan yarışlar</button><span class="muted small">${L.currentRound} GP + ${new Set(L.results.filter(r=>r.session==='Sprint').map(r=>r.round)).size} sprint tamamlandı</span></div><div class="race-grid">${L.races.filter(r=>!onlyCompleted||r.completed).map(r=>{const winner=raceRows(r.round)[0];return `<a class="race-card ${r.completed?'completed':''}" href="${href('race',r.round)}"><div class="race-photo" style="background-image:url('${r.photo}')"><span class="round-chip">ROUND ${String(r.round).padStart(2,'0')}</span>${flag(r.round)}</div><div class="race-card-body"><span class="small ${r.completed?'completed-label':'muted'}">${r.classificationStatus==='provisional'?'GEÇİCİ KLASMAN':r.completed?'TAMAMLANDI':r.round===currentRound+1?'SIRADAKİ YARIŞ':'SEZON TAKVİMİ'}</span><h2>${h(r.name)}</h2><p>${h(r.circuit)}</p><div class="race-winner">${winner?`${logo(winner.team)}<span><small>${r.classificationStatus==='provisional'?'GEÇİCİ LİDER':'YARIŞ KAZANANI'}</small><b>${h(winner.name)}</b></span>`:`<span class="muted">${r.startsAt?h(r.dateLabel)+(r.scheduleConfirmed===false?' · Planlanan':''):'Tarih açıklanacak'}</span>`}<span class="race-arrow">↗</span></div>${hasSprint(r.round)?'<span class="sprint-tag">SPRINT + YARIŞ</span>':r.sprintStatus==='unconfirmed'?'<span class="sprint-tag sprint-unconfirmed">SPRINT BİLGİSİ BEKLENİYOR</span>':!r.completed&&r.sprintStatus==='confirmed'?'<span class="sprint-tag">SPRINT YOK · GRAND PRIX</span>':''}</div></a>`}).join('')}</div>`;}
function resultTable(inputRows){const sourceRows=performanceRows({session:'all'});const rows=inputRows.map(r=>{const o=sourceRows.find(x=>x.name===r.name&&x.round===r.round&&x.session===r.session);return o?.observed?{...r,grid:o.grid,pitStops:o.pitStops,bestLapMs:o.bestLapMs}:r;});const detailed=rows.some(r=>r.bestLapMs),timed=rows.some(r=>r.gapMs!=null||r.lapsBehind>0),best=Math.min(...rows.map(r=>r.bestLapMs||Infinity));return `<div class="table-scroll"><table class="standings-table result-table"><thead><tr><th>SIRA</th><th>PİLOT / YARIŞ TAKIMI</th><th class="hide-small">GRİD</th>${detailed?'<th class="hide-small">PİT</th><th class="hide-small">EN İYİ TUR</th>':''}${timed?'<th>SÜRE / FARK</th>':''}<th>DURUM</th><th>PUAN</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b class="rank ${r.position&&r.position<=3?'rank-'+r.position:''}">${r.positionLabel?h(r.positionLabel):String(r.position??'—').padStart(2,'0')}</b></td><td><div class="driver-cell">${logo(r.team)}<div>${driverLink(r.name)}${teamLabel(r.team)}${r.sourceNote?`<small class="source-note">${h(r.sourceNote)}</small>`:''}</div></div></td><td class="hide-small">${r.grid??'—'}</td>${detailed?`<td class="hide-small">${r.pitStops??'—'}</td><td class="hide-small ${r.bestLapMs===best?'fastest-lap':''}">${msLabel(r.bestLapMs)}</td>`:''}${timed?`<td>${r.status==='DNF'?'—':r.lapsBehind>0?'+'+r.lapsBehind+' tur':r.gapMs===0?msLabel(r.elapsedMs):r.gapMs!=null?'+'+msLabel(r.gapMs):'—'}</td>`:''}<td><span class="result-status ${r.status==='FIN'?'finished':''}">${r.classified&&r.status==='DNF'?'DNF · Klasmanda':r.status==='FIN'?'FİNİŞ':h(r.status)}</span></td><td><strong class="table-points">${r.points??'—'}</strong></td></tr>`).join('')}</tbody></table></div>`;}
function racePage(){const r=gp(Number(value));if(!r)return notFound();const sprint=raceSession==='Sprint';
 const rows=raceRows(r.round,raceSession),top=rows.slice(0,3);
 const cases=driverCases().filter(p=>p.round===r.round&&(sprint?p.session==='Sprint':p.session!=='Sprint'));
 const resultSource=sprint?r.sprintClassificationSourceUrl:r.classificationSourceUrl;
 const analysisCount=sprint?analysisInfo.sprintEvents?.[r.round]:analysisInfo.races?.[r.round];
 const analysisUrl='analiz/?round='+r.round+(sprint?'&session=sprint':'');return `${link('races','← Yarış takvimi','back-link')}${heading('ROUND '+String(r.round).padStart(2,'0')+' · 2026',flag(r.round)+' '+h(r.name).toUpperCase()+' GP',h(r.circuit),'<span class="outline-tag">'+(r.classificationStatus==='provisional'?'GEÇİCİ KLASMAN':r.classificationStatus==='final'?'RESMÎ SONUÇ':r.completed?'TAMAMLANDI':'TAKVİMDE')+'</span>')}`+(r.completed?`<section class="race-podium"><div class="race-podium-title"><p class="eyebrow">DAMALI BAYRAĞIN ARDINDAN</p><h2>${r.classificationStatus==='provisional'?'Geçici ':''}${raceSession==='Sprint'?'Sprint':'Yarış'} podyumu</h2></div><div class="podium-large">${[top[1],top[0],top[2]].filter(Boolean).map(x=>`<a href="${href('pilot',pilot(x.name)?.id||'')}" class="large-place large-place-${x.position}" style="--team:${team(x.team).color}"><span class="large-rank">${x.position}</span><div class="large-face">${avatar(pilot(x.name))}</div><div class="large-person"><small>${x.position===1?(r.classificationStatus==='provisional'?'GEÇİCİ LİDER':'YARIŞ KAZANANI'):x.position+'. SIRA'}</small><h3>${h(x.name)}</h3><span>${logo(x.team)}${h(x.team)}</span><b>${x.points} PUAN</b></div></a>`).join('')}</div></section>${hasSprint(r.round)?`<div class="tab-row"><button class="${raceSession==='Yarış'?'selected':''}" data-session="Yarış">Grand Prix sonuçları</button><button class="${raceSession==='Sprint'?'selected':''}" data-session="Sprint">Sprint sonuçları</button></div>`:''}<section class="panel">${resultTable(rows)}</section>${link('statistics','Başlangıç → bitiş istatistikleri ↗','text-button',String(r.round))}${analysisCount?`<aside class="race-analysis-link"><div><span class="eyebrow">BU GRAND PRIX’NİN KAYDI</span><h3>Yarışın hikâyesini keşfet.</h3><p>Pozisyon ve tempo grafikleri, ${analysisCount} olaylık zaman çizelgesi, günün sürücüsü ve sanal hasar bütçesi.</p></div><a class="button primary" href="${analysisUrl}">${sprint?'Sprint':'Yarış'} raporunu aç</a><a class="button secondary" href="${analysisUrl}#timeline">Zaman çizelgesine bak</a></aside>`:''}<p class="data-note">Başlangıç, pit ve kişisel en iyi tur oyun ekranı ve telemetriden. ${r.classificationStatus==='provisional'?'Sıra ve puanlar geçici hesap.':'Sıra ve puanlar resmî klasmandan.'}</p><p class="data-note">${r.classificationNote?h(r.classificationNote):'Cezalar uygulanmış kesin sonuçlar. Süre/fark verisi paylaşılmadı.'} FIN: finiş · DNF: yarış dışı · DNS: start almadı · WD: çekildi · DNP: katılmadı · DSQ: diskalifiye.</p>${resultSource||r.sourceImage?`<p class="data-note"><a class="text-button" href="${h(resultSource||r.sourceImage)}" target="_blank" rel="noopener">${resultSource?(sprint?'Discord · Resmî sprint sonucu':'Discord · Resmî yarış sonucu'):'Yönetimin paylaştığı sonuç görseli'}</a></p>`:''}${cases.length?`<div class="section-heading"><div><p class="eyebrow">BU GRAND PRIX’DEN</p><h2>FIA kararları</h2></div></div><div class="decision-grid">${cases.map(penaltyCard).join('')}</div>`:''}`:`<div class="upcoming panel"><span class="upcoming-round">${String(r.round).padStart(2,'0')}</span><p class="eyebrow">${r.round===currentRound+1?'SIRADAKİ GRAND PRIX':'2026 SEZON TAKVİMİ'}</p><h2>${h(r.name)} GP</h2>${r.startsAt?countdownBanner(r.round)+scheduleNotice()+(r.round===currentRound+1?pendingBanner():''):'<p>Yarış tarihi henüz açıklanmadı. Sonuçlar ve kararlar yarış sonrasında burada yer alacak.</p>'}${link('races','Takvime dön →','button secondary')}</div>`);}
const principal=t=>t.principal?`<p class="team-principal"><span>Takım patronu</span><b>${h(t.principal)}</b></p>`:'';
function rosterSeat(p){if(!p)return `<div class="roster-driver vacant"><div class="vacant-symbol">+</div><div class="roster-driver-info"><span class="eyebrow">BOŞ KOLTUK</span><h3>Pilot bekleniyor</h3><p>Aktif kadroda pilot yok.</p></div></div>`;const st=stats(p.name),dp=licence(p.name);return `<a href="${href('pilot',p.id)}" class="roster-driver"><div class="roster-portrait">${avatar(p)}</div><div class="roster-driver-info"><span class="eyebrow">${p.seat}. PİLOT</span><h3>${h(p.displayName||p.name)}</h3><span class="representative">${p.gameName?'Oyun adı · '+h(p.gameName):'Oyun adı bekleniyor'}</span><span class="representative">${p.representative?h(p.representative)+' · temsilî portre':'Temsilî portre henüz eklenmedi'}</span><div class="roster-driver-stats"><span><b>${st.points}</b> PUAN</span><span><b>${dp.points}</b> DP</span><span aria-hidden="true">↗</span></div></div></a>`;}
function rosterSearchText(value){
  return String(value || '').toLocaleLowerCase('tr').replaceAll('ı','i').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
}
function driversPage(){const query=rosterSearchText(driverSearch.trim()),filtered=teamStandings().filter(t=>(teamFilter==='all'||t.name===teamFilter)&&(rosterSearchText(t.name).includes(query)||teamMembers(t.name).some(p=>[p.name,p.displayName,p.gameName,...(p.gameAliases||[])].some(label=>rosterSearchText(label).includes(query)))));return heading('FPL 2026 · TAKIMLAR','11 TAKIM. TEK HEDEF.','Araçlar, güncel kadrolar ve takımın hikâyesi. Takımlar şampiyona sırasına göre listelenir.')+`<div class="filters"><label class="search-field"><span>Takım, pilot veya oyun adı ara</span><input type="search" id="driverSearch" placeholder="Takım, pilot veya oyun adı…" value="${h(driverSearch)}"></label>${select('teamFilter','Takım',[['all','Tüm takımlar'],...teamStandings().map(t=>[t.name,t.name])],teamFilter)}<span class="filter-count">${filtered.length} takım · ${filtered.reduce((n,t)=>n+teamMembers(t.name).length,0)} aktif pilot</span></div><section class="team-roster-list">${filtered.map(t=>{const members=teamMembers(t.name);return `<article class="team-roster" style="--team:${t.color}"><div class="roster-heading"><div class="roster-team-name"><span class="roster-rank">${String(t.rank).padStart(2,'0')}</span>${logo(t.name)}<div class="roster-team-title"><h2>${h(t.name)}</h2>${principal(t)}</div></div><div class="roster-team-score"><b>${t.points}</b> PUAN ${link('team','Takımı keşfet ↗','text-button',t.name)}</div></div><div class="roster-content"><a class="roster-car" href="${href('team',t.name)}" aria-label="${h(t.name)} takım profili"><span class="roster-car-label">2026 SEZONU</span><img src="${t.car}" alt="${h(t.name)} 2026 yarış aracı" loading="lazy"></a><div class="roster-seats">${[members.find(p=>p.seat===1),members.find(p=>p.seat===2)].map(rosterSeat).join('')}</div></div></article>`}).join('')||'<div class="empty">Bu aramaya uygun takım bulunamadı.</div>'}</section><p class="data-note">Güncel kadrolar gösterilir. Portreler temsilî gerçek F1 pilotlarıdır; lig pilotlarının Discord fotoğrafları kullanılmaz. Boş koltuklara pilot atanmaz.</p><div class="section-heading"><div><p class="eyebrow">YENİ RENKLER. AYNI MÜCADELE.</p><h2>Transfer geçmişi</h2></div></div><div class="transfer-grid">${L.transfers.slice().reverse().map(t=>`<article class="transfer-card"><h3>${driverLink(t.name)}</h3><div>${t.from?logo(t.from):''}<span>${h(t.from||'Önceki takım paylaşılmadı')}</span><b>→</b>${t.to?logo(t.to):''}<span>${h(t.to||'Kadrodan ayrıldı')}</span></div><p>${h(t.note)}</p><small>Geçmiş yarış puanları yarıştığı takımda kalır.</small></article>`).join('')}</div>`;}
function overallFor(p){return ratingCards.find(c=>c.pilotId===p.id);}
function overallProfile(p){if(p.active===false)return '';const card=overallFor(p);return `<section class="overall-profile panel" style="--team:${team(p.team).color}"><div class="overall-profile-rating"><strong>${card.current}</strong><span>OVR</span><b class="${card.delta>0?'up':card.delta<0?'down':''}">${card.reviewCount?(card.delta>0?'+':'')+card.delta:'BAŞLANGIÇ'}</b></div><div><p class="eyebrow">KALICI PİLOT KARTI</p><h2>Genel reyting</h2><p>${card.reviewCount?'Son güncelleme: R'+card.lastRound+' · '+h(card.history.at(-1).gp)+' · Yarış notu '+card.lastScore.toFixed(1).replace('.',',')+' / 10':'80 nötr başlangıç. Henüz değerlendirilmiş yarış yok.'}</p><small>Bakü’den itibaren yarış başına en fazla ±${ratingPolicy.maxChange} OVR.</small></div><a class="button secondary" href="#pilot-cards">Pilot kartlarını incele</a></section>`;}
function pilotPage(){const p=L.pilots.find(p=>p.id===value);if(!p)return notFound();const st=stats(p.name),dp=licence(p.name),rank=standings().find(x=>x.id===p.id),cases=driverCases(p.name),affiliation=currentAffiliation(p);return `${link('teams','← Takımlara dön','back-link')}<section class="profile-hero ${p.active===false?'departed-profile':''}" style="--team:${affiliation.color}"><div class="profile-copy"><p class="eyebrow">FPL 2026 · PİLOT PROFİLİ</p>${affiliationLabel(p)}<h1>${h(p.displayName||p.name)}</h1>${p.gameName?`<p class="muted">OYUN İÇİ NİCK · <b>${h(p.gameName)}</b></p>`:''}<div class="profile-stats"><span><b>${rank?.rank??'—'}</b>${p.active===false?'SIRALAMA DIŞI':'ŞAMPİYONA SIRASI'}</span><span><b>${st.points}</b>PUAN</span><span><b>${st.wins}</b>GALİBİYET</span><span><b>${st.podiums}</b>PODYUM</span></div>${p.active===false?link('standings','Aktif sıralamaya bak ↗','text-button'):link('team','Takımı keşfet ↗','text-button',p.team)}</div>${p.active===false?`<div class="departed-profile-art"><img src="${h(affiliation.logo)}" alt="${h(affiliation.name)} simgesi"><span>FPL · PİLOT ARŞİVİ</span><strong>${h(affiliation.name.toLocaleUpperCase('tr'))}</strong><p>Aktif takımda yer almıyor.</p></div>`:`<div class="profile-art">${logo(p.team)}<img src="${team(p.team).car}" alt="${h(p.team)} 2026 aracı"></div>`}</section>${overallProfile(p)}${p.pointsStartRound?`<aside class="points-reset-note"><b>Yeniden başlangıç · R${String(p.pointsStartRound).padStart(2,'0')}</b><p>Lig yönetiminin kararıyla şampiyona puanları bu yarıştan itibaren sıfırdan hesaplanır. Önceki ${st.archivedPoints} puan arşivde kalır; aktif toplamına eklenmez. Geçmiş yarış ve takım puanları korunur.</p></aside>`:''}<section class="profile-licence panel"><div><span class="eyebrow">SÜRÜCÜ LİSANSI</span><h2>${dp.points}<small> DP</small></h2><span class="status-pill ${dp.points>=6?'warning':''}">${dp.status}</span></div><div><b>${dp.next?'İlk puan silinmesi: '+h(dp.next.expiresGP)+' GP':'Kayıtlı aktif ceza puanı yok.'}</b><p>${dp.next?`${dp.remaining} yarış sonra · R${dp.next.expires} sonrası FIA kararları kesinleşince.`:'Disiplin puanları şampiyona puanından ayrıdır.'}</p>${link('licence','Puan silinme takvimini gör ↗','text-button')}</div></section>${pilotPerformance(p)}<div class="section-heading"><h2>Yarış geçmişi</h2></div><section class="panel"><div class="table-scroll"><table class="standings-table"><thead><tr><th>YARIŞ</th><th>SEANS</th><th>YARIŞ TAKIMI</th><th>SONUÇ</th><th>PUAN</th></tr></thead><tbody>${st.results.map(r=>`<tr class="${p.pointsStartRound&&r.round<p.pointsStartRound?'archived-result':''}"><td>${link('race',flag(r.round)+' '+h(r.gp)+' GP','text-button',String(r.round))}</td><td>${h(r.session)}</td><td>${teamLabel(r.team)}</td><td>${(r.status==='FIN'||r.classified)?(r.positionLabel?h(r.positionLabel):'P'+r.position):h(r.status)}</td><td><b class="table-points">${r.points}</b>${p.pointsStartRound&&r.round<p.pointsStartRound?'<small class="source-note">Arşiv · aktif toplama dahil değil</small>':''}</td></tr>`).join('')}</tbody></table></div></section><div class="section-heading"><h2>FIA ceza geçmişi</h2><span class="small muted">${cases.length} ayrı kayıt</span></div><div class="decision-grid">${cases.map(penaltyCard).join('')||'<div class="empty">Bu pilot için kayıtlı FIA cezası yok.</div>'}</div>${p.representative&&p.active!==false?`<p class="data-note">Temsilî profil portresi: ${h(p.representative)}. ${p.active===false?'Bu pilotun aktif takımı yoktur. Tarihî yarış kayıtlarında o yarıştaki takımı ve puanları korunur.':'Güncel takım gösterilir; geçmiş yarış puanları yarıştaki takımında kalır.'}</p>`:''}`;}
function teamPage(){const t=team(value);if(!L.teams.some(t=>t.name===value))return notFound();const members=teamMembers(value),st=teamStandings().find(x=>x.name===value);return `${link('standings','← Puan durumuna dön','back-link')}<section class="profile-hero" style="--team:${t.color}"><div class="profile-copy"><p class="eyebrow">FPL 2026 · TAKIM PROFİLİ</p>${logo(t.name)}<h1>${h(t.name)}</h1>${principal(t)}<div class="profile-stats"><span><b>${st.rank}</b>TAKIM SIRASI</span><span><b>${st.points}</b>PUAN</span></div></div><div class="profile-art"><img src="${t.car}" alt="${h(t.name)} 2026 aracı"></div></section><div class="section-heading"><h2>Güncel pilotlar</h2></div><div class="team-members">${members.map(p=>`<a href="${href('pilot',p.id)}" class="panel member-card">${avatar(p)}<div><h2>${h(p.name)}</h2><span class="member-ovr">${overallFor(p).current} OVR</span><p>Pilot profiline git ↗</p></div></a>`).join('')||'<div class="empty">Güncel aktif kadroda pilot bulunmuyor.</div>'}</div><div class="section-heading"><h2>Takımın yarış puanları</h2></div><section class="panel"><div class="table-scroll"><table class="standings-table"><thead><tr><th>GRAND PRIX</th><th>YARIŞ PUANI</th><th>SPRINT PUANI</th><th>TOPLAM</th></tr></thead><tbody>${L.races.filter(r=>r.completed).map(r=>{const results=L.results.filter(x=>x.round===r.round&&x.team===t.name),race=results.filter(x=>x.session==='Yarış').reduce((n,x)=>n+x.points,0),sprint=results.filter(x=>x.session==='Sprint').reduce((n,x)=>n+x.points,0);return `<tr><td>${link('race',flag(r.round)+' '+h(r.name)+' GP','text-button',String(r.round))}</td><td>${race}</td><td>${sprint}</td><td><b>${race+sprint}</b></td></tr>`}).join('')}</tbody></table></div></section><p class="data-note">Bu tablo, transfer olan veya ligden ayrılan pilotların bu takımda kazandığı puanları da içerir.</p>`;}
function notFound(){return `<section class="empty"><h1>Bu sayfa bulunamadı.</h1>${link('home','Lig merkezine dön →','button primary')}</section>`;}
function render(){clearInterval(countdownTimer);pageShell();$('#main').innerHTML=classificationNotice()+(route==='rules'?gridPolicyNotice():'')+({home,standings:standingsPage,decisions:decisionsPage,licence:licencePage,races:racesPage,race:racePage,teams:driversPage,'pilot-cards':cardsPage,pilot:pilotPage,team:teamPage,news:newsPage,statistics:statisticsPage,rules:rulesPage}[route]||notFound)();$('#main').dataset.ready='true';document.title=(route==='home'?'':route==='pilot'?(L.pilots.find(p=>p.id===value)?.name||'Pilot')+' | ':route==='race'?(gp(Number(value))?.name||'Grand Prix')+' GP | ':(routes.find(x=>x[0]===route)?.[1]||'Takım')+' | ')+'FPL • Paddock League';startCountdown();}
function navigate(){setMenuOpen(false,false);const [r,v,session]=(location.hash.slice(1)||'home').split('/');route=r==='home'&&v==='pilot-cards'?'pilot-cards':({drivers:'teams',control:'home',calendar:'races',results:'races',licence:'licence'}[r]||r);try{value=decodeURIComponent(v||'')}catch{value=''}raceSession=route==='race'&&session==='sprint'&&hasSprint(value)?'Sprint':'Yarış';if(route==='statistics'&&value){const chosen=L.pilots.find(p=>p.id===value);statsPilot=chosen?.name||'all';statsRound=chosen?'all':Number.isInteger(Number(value))?value:'all';statsSession='Yarış';}closeDetail();render();window.scrollTo({top:0,behavior:'auto'});}
function openRatingCard(id){
 const p=L.pilots.find(p=>p.id===id);if(!p)return;
 const r=overallFor(p);
 const lastReview=ratingReviews.find(review=>review.round===r.lastRound)?.assessments.find(item=>item.pilotId===p.id);
 const deductions=ratingBreakdownText(lastReview?.breakdown);
 const note=lastReview?'<h3>Son yarışın değerlendirmesi</h3><p>'+h(lastReview.reason)+'</p>'+(deductions?'<p class="fine-line">'+h(deductions)+'</p>':''):'';
 openDialog(`<div class="dialog-title"><img src="${h(p.portrait)}" alt="${h(p.name)} için temsilî ${h(p.representative)} portresi"><div><p class="eyebrow">FPL · KALICI PİLOT KARTI</p><h2 id="dialog-title">${h(p.name)}</h2><span class="muted">${h(p.team)}</span></div></div><div class="overall-dialog-value">${r.current}<span>OVR</span><small class="${r.delta>0?'green':r.delta<0?'red':''}">${r.reviewCount?(r.delta>0?'+':'')+r.delta+' · son güncelleme':'80 nötr başlangıç'}</small></div><p>OVR uzun dönem kart değeridir. Son yarış notu ${r.lastScore==null?'henüz verilmedi':r.lastScore.toFixed(1).replace('.',',')+' / 10'}.</p>${note}<h3>Kart geçmişi</h3><p class="muted">Başlangıç: 80 OVR. Önceki yarışlara not atanmadı.</p><div class="table-scroll"><table class="standings-table"><thead><tr><th>Grand Prix</th><th>Yarış notu</th><th>Önceki</th><th>Yeni</th><th>Değişim</th></tr></thead><tbody>${r.history.map(x=>`<tr><td>R${x.round} · ${h(x.gp)}</td><td>${x.score.toFixed(1).replace('.',',')}</td><td>${x.previous}</td><td>${x.current}</td><td class="${x.delta>0?'green':x.delta<0?'red':''}">${x.delta>0?'+':''}${x.delta}</td></tr>`).join('')||'<tr><td colspan="5">Henüz değerlendirilmiş yarış yok; kart 80’de korunuyor.</td></tr>'}</tbody></table></div><p class="fine-line">Bakü’den itibaren yarış başına değişim en fazla ±${ratingPolicy.maxChange} OVR. Notu olmayan yarış OVR’yi değiştirmez. Aynı Grand Prix tekrar işlendiğinde ikinci kez puan uygulanmaz.</p><a class="text-button" href="#pilot/${h(p.id)}">Pilot profiline git</a>`,'dialog-title');
}
function openDialog(html,labelledBy){$('#detail').innerHTML=`<div class="dialog-head"><span class="eyebrow">FPL PADDOCK LEAGUE</span><button data-close aria-label="Pencereyi kapat">×</button></div>${html}`;const detail=$('#detail');if(labelledBy)detail.setAttribute('aria-labelledby',labelledBy);else detail.removeAttribute('aria-labelledby');if(typeof detail.showModal==='function')detail.showModal();else{detail.setAttribute('open','');detail.classList.add('dialog-fallback');}}
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();document.querySelector("#main").focus();return;}const b=e.target.closest('button');if(!b)return;if(b.dataset.ratingPilot){openRatingCard(b.dataset.ratingPilot);return;}if('cardReset'in b.dataset){resetCardFilters();return;}if(b.dataset.champ){champ=b.dataset.champ;render()}if(b.dataset.calendar){onlyCompleted=b.dataset.calendar==='done';render()}if(b.dataset.session){
  raceSession=b.dataset.session;
  history.replaceState(null,'',href('race',value)+(raceSession==='Sprint'?'/sprint':''));
  render();
 }if('reset'in b.dataset){decisionPilot=decisionRound=decisionType='all';render()}if('close'in b.dataset)closeDetail();if(b.dataset.case){const p=L.penalties.find(x=>x.id===b.dataset.case);if(!p)return;openDialog(`<div class="dialog-gp">${flag(p.round)} ${h(p.gp)} GP · R${String(p.round).padStart(2,'0')}</div><h2>${h(p.name)}</h2><div class="dialog-sanction"><strong>${h(sanction(p))}</strong><span>${dpText(p)}</span></div>${p.type==='Grid'&&p.gridPolicy!=='FPL-R09-BACK'?`<div class="grid-dialog-note"><b>+${p.originalSeconds} sn → ${p.amount} sıra grid</b><p>${h(p.conversionBasis)}</p><p>${gridTransferSummary(p)}</p></div>`:''}${dpCleared(p)?`<div class="dp-clear-note"><b>DP aktif toplamdan silindi</b><p>Bu kayıttaki ${p.points} DP arşivde tutulur. ${h(p.dpClearReason)}</p></div>`:''}${p.applicationNote?`<p class="data-note">${h(p.applicationNote)}</p>`:''}${p.dpBasis?`<div class="dp-basis"><b>Disiplin puanı gerekçesi</b><p>${h(p.dpBasis)}</p></div>`:''}${p.lap?`<p class="decision-lap">OLAY TURU · ${p.lap}</p>`:''}<h3>Karar gerekçesi</h3><p class="full-reason">${h(p.reason)}</p>${p.sourceUrl?`<p><a class="text-button" href="${h(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">Discord karar bülteni ↗</a></p>`:''}<div class="dialog-facts"><div><small>SEANS</small><b>${h(p.session)}${p.lap?' · '+p.lap+'. tur':''}</b></div><div><small>PUAN SİLİNMESİ</small><b>${p.points==null?(p.dpStatus==='not_specified'?'Ek DP belirtilmedi':'DP kararı bekleniyor'):p.expires?h(p.expiresGP)+' GP · R'+p.expires:'—'}</b></div><div><small>KALAN SÜRE</small><b>${p.expires==null?'—':Math.max(0,p.expires-currentRound)+' yarış'}</b></div><div><small>YAPTIRIMIN UYGULANMASI</small><b>${p.applicationStatus==='onHold'?'Takımsız · Uygulama beklemede':p.type==='DP kaydı'?'R'+p.round+' · Ek disiplin kaydı':p.applicationStatus==='served'?(p.serviceEvidence?h(p.serviceEvidence):'Çekildi / kapatıldı · Lig yönetimi'):p.decisionStatus==='pending'?'Yaptırım ve DP bekleniyor':p.gridPolicy==='FPL-R09-BACK'?'Sonraki GP sondan başlama':p.applicationStatus==='pending'?'Uygulama kararı bekleniyor':p.applicationStatus==='recorded'?(p.resultStatus==='DSQ'?'Resmî klasman · DSQ':'Disiplin kaydına işlendi'):p.applicationStatus==='closed'?'İnceleme kapatıldı':p.applicationStatus==='provisional'?'Geçici klasman · R'+p.round:p.applies?'R'+p.applies+(p.type==='Grid'&&p.applies>p.round?' · Sonraki katılacağı Grand Prix · Sprint değil':''):'Ayrıntı paylaşılmadı'}</b></div></div><p class="data-note">Puanlar ilgili GP tamamlanıp FIA kararları kesinleşince aktif toplamdan düşer. Geçmiş karar arşivde kalır.</p>${p.rules?.length?`<h3>Yönetmelik dayanağı</h3><p>${p.rules.map(x=>link('rules','Madde '+x,'text-button',x.split('.')[0])).join(' · ')}</p>`:''}${p.components?`<h3>Kararın ayrı ihlalleri</h3>${p.components.map(x=>`<p>${h(x.reason)}: <b>+${x.seconds} sn · +${x.points} DP</b></p>`).join('')}`:''}<p class="application-pill ${applicationState(p)}">${applicationLabel(p)}${p.decisionStatus==='pending'?' · Yaptırım ve DP miktarı açıklanmadı.':p.extraGridReview?' · Ek grid uygulaması bekleniyor.':p.applicationStatus==='pending'&&p.type==='Grid'?' · Grid uygulaması bekleniyor.':''}</p><p class="data-note">İtiraz süresi: kararın yayımlanmasından itibaren 24 saat (Madde 19.2). İnceleme ve karar yetkisi FPL hakem kurulundadır.</p><div class="dialog-actions">${pilot(p.name)?link('pilot','Pilot profili ↗','button secondary',pilot(p.name).id):''}${link('licence','Ceza puanları →','button primary')}</div>`)}if('about'in b.dataset)openDialog('<h2>FPL Paddock League</h2><p>2026 sezonu lig kayıtları. Avusturya’nın resmî sprint ve yarış klasmanları ile hakem kararları yer alıyor. Bu sayfa lig yönetiminin paylaştığı sonuçları ve kararları görüntüler.</p><p>Bekleyen yaptırımlar, çekilen cezalar ve hakem kararları FIA arşivinde gösterilir. Eksik toplam süre ve ek DP bilgileri ilgili kayıtlarda belirtilir. Kararları yetkili hakemler verir.</p><h3>Görsel kaynakları</h3><p>Araç görselleri, takım logoları, GP görselleri ve temsilî pilot portreleri Formula1.com; ülke bayrakları FlagCDN kaynaklıdır. GP görselleri temsilîdir. FPL bağımsız bir sim yarış ligidir.</p><p>Portreler lig pilotlarının gerçek fotoğrafları değildir; takım koltuğuna göre seçilmiş temsilî F1 pilotlarıdır.</p><a class="text-button" href="https://www.formula1.com/en/teams" target="_blank" rel="noopener noreferrer">Formula 1 görsel kaynakları ↗</a>');});
document.addEventListener('change',e=>{const key=e.target.id,v=e.target.value;
 if(key==='card-team'||key==='card-order'){
  cardFilters[key==='card-team'?'team':'order']=v;
  refreshCardResults();
  return;
 }
 if(key==='statsRound')statsRound=v;if(key==='statsSession')statsSession=v;if(key==='statsPilot')statsPilot=v;if(['statsRound','statsSession','statsPilot'].includes(key)){render();return;}if(key==='decisionPilot')decisionPilot=v;if(key==='decisionRound')decisionRound=v;if(key==='decisionType')decisionType=v;if(key==='teamFilter')teamFilter=v;if(['decisionPilot','decisionRound','decisionType','teamFilter'].includes(key))render();});
document.addEventListener('input',e=>{
 if(e.target.id==='card-search'){
  cardFilters.search=e.target.value;
  refreshCardResults();
  return;
 }
 if(e.target.id==='ruleSearch'){ruleQuery=e.target.value;const pos=e.target.selectionStart;render();$('#ruleSearch')?.focus();$('#ruleSearch')?.setSelectionRange(pos,pos);}if(e.target.id==='driverSearch'){driverSearch=e.target.value;const start=e.target.selectionStart;render();$('#driverSearch')?.focus();$('#driverSearch')?.setSelectionRange(start,start);}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDetail();}});window.addEventListener('hashchange',navigate);

function scheduleNotice(){return L.schedule?`<aside class="schedule-notice"><div><span class="eyebrow">LİG YARIŞ PROGRAMI</span><strong>${h(L.schedule.daysLabel)} <em>21.00</em></strong><small>Türkiye saati · Gelecek tarihler standart programa göre planlanmıştır.</small></div><p>${h(L.schedule.sprintNote)}</p></aside>`:'';}
function countdownBanner(round=L.nextWeekend.round){const next=gp(round),isNext=round===L.nextWeekend.round,weekend=isNext?L.nextWeekend:{startsAt:next.startsAt,label:next.dateLabel,statusLabel:next.statusLabel,confirmed:next.scheduleConfirmed};return `<section class="countdown-banner"><div><p class="eyebrow">${isNext?'SIRADAKİ DURAK':'SEZON TAKVİMİ'} · ROUND ${String(next.round).padStart(2,'0')}</p><h2>${flag(next.round)} ${h(next.name).toLocaleUpperCase('tr')} <span>${next.sprintStatus==='unconfirmed'?'SPRINT TEYİDİ BEKLENİYOR':hasSprint(next.round)?'SPRINT HAFTA SONU':'GRAND PRIX · SPRINT YOK'}</span></h2><p>${h(weekend.label)}${weekend.statusLabel?' · '+h(weekend.statusLabel):''}</p></div>${weekend.startsAt?`<div class="countdown" data-countdown data-countdown-round="${round}" role="timer" aria-label="Planlanan yarış başlangıcına kalan süre"></div>`:'<span class="schedule-pending">TAKVİM BİLGİSİ BEKLENİYOR</span>'}<a href="#race/${next.round}" class="text-button">Hafta sonuna bak ↗</a></section>`;}
function startCountdown(){const box=$('[data-countdown]');if(!box)return;const race=gp(Number(box.dataset.countdownRound));const update=()=>{const c=countdownState(Date.now(),race.startsAt);box.innerHTML=c.started?'<strong>'+(race.scheduleConfirmed===false?'Planlanan saat geldi':'Hafta sonu başladı')+'</strong>':[['days','GÜN'],['hours','SAAT'],['minutes','DAKİKA'],['seconds','SANİYE']].map(([k,t])=>`<span><b>${String(c[k]).padStart(2,'0')}</b><small>${t}</small></span>`).join('');if(c.started)clearInterval(countdownTimer);};update();if(!countdownState(Date.now(),race.startsAt).started)countdownTimer=setInterval(update,1000);}

function pendingBanner(){return L.pendingSanctions.filter(p=>p.status!=='served'&&p.status!=='onHold').map(p=>p.type==='Grid'?`<aside class="pending-banner grid-carryover"><span class="pending-icon">↘</span><div><p class="eyebrow">SONRAKİ KATILACAĞI GRAND PRIX · GRİD CEZASI</p><h3>${driverLink(p.name)} <span class="grid-total">${p.gridPolicy==='FPL-R09-BACK'?'SONDAN BAŞLAMA':p.amount+' SIRA GRİD'}</span></h3><p>${h(p.reason)}</p><strong>${p.targetRound?'R'+p.targetRound+' · ':''}Grand Prix · ${p.points??'—'} DP</strong><p class="data-note">Grid cezası alan pilotlar yeni FPL kuralıyla gridin arka grubundan başlar. Birden fazla cezalı pilotun kesin start sırası yönetimce belirlenecek.</p></div></aside>`:`<aside class="pending-banner"><span class="pending-icon">!</span><div><p class="eyebrow">${p.type==='Men'&&p.status==='scheduled'?(gp(p.targetRound)?.name||'SONRAKİ GP').toLocaleUpperCase('tr')+' GP · YARIŞTAN MEN':'EK YAPTIRIM · KARAR BEKLİYOR'}</p><h3>${driverLink(p.name)}</h3><p>${h(p.reason)}</p></div></aside>`).join('');}
function newsPeriod(n){return n.publishedAt?new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'}).format(new Date(n.publishedAt+'T12:00:00Z')):`${gp(n.round)?.name||''} GP SONRASI`;}
function newsCard(n){return `<a class="news-card" href="${href('news',n.id)}" style="--team:${team(n.team).color}"><div class="news-image"><span>${h(n.category)}</span><img src="${team(n.team).car}" alt="${h(n.team)} 2026 yarış aracı" loading="lazy">${logo(n.team)}</div><div class="news-copy"><small>${h(newsPeriod(n)).toLocaleUpperCase('tr')}${n.publishedAt?'':' · 2026'}</small><h2>${h(n.title)}</h2><p>${h(n.summary)}</p><b>Haberi oku ↗</b></div></a>`;}
function newsPage(){if(value){const n=L.news.find(n=>n.id===value);if(!n)return notFound();return link('news','← Paddock haberleri','back-link')+`<article class="news-article"><div class="news-article-art" style="--team:${team(n.team).color}"><img src="${team(n.team).car}" alt="${h(n.team)} yarış aracı"></div><p class="eyebrow">${h(n.category)} · ${h(newsPeriod(n)).toLocaleUpperCase('tr')}</p><h1>${h(n.title)}</h1><p class="news-lead">${h(n.summary)}</p><p>${h(n.body)}</p>${link(n.route,'İlgili sayfayı keşfet ↗','button primary',n.value)}</article>`;}return heading('FPL · PADDOCK HABERLERİ','PİSTİN DIŞINDAKİ HİKÂYE.','Güncel kadrolar, koltuk değişiklikleri ve hafta sonundan notlar. Yalnız lig yönetiminin doğruladığı bilgiler.')+`<div class="news-grid">${L.news.map(newsCard).join('')}</div>`;}
function rulesPage(){const query=ruleQuery.toLocaleLowerCase('tr'),visible=rules.filter(r=>!query||(r.number+' '+r.title+' '+r.body).toLocaleLowerCase('tr').includes(query));return heading('FPL 2026 · SPORTİF YÖNETMELİK','KURAL KİTAPÇIĞI.','23 madde. Tek referans. Lig yönetiminin yayımladığı metin; karar yetkisi hakem kurulunda.',`<a class="button secondary" href="assets/fpl-sportif-yonetmelik-2026.txt" download>Kitapçığı indir ↓</a>`)+`<section class="rule-highlights"><a href="#rules/4"><b>ATAK & SAVUNMA</b><span>Madde 4</span></a><a href="#rules/15"><b>10 YARIŞ GEÇERLİLİK</b><span>6 / 9 / 12 DP · Madde 15 & 21</span></a><a href="#rules/20"><b>DNF & YAPTIRIMLAR</b><span>Madde 20.2</span></a></section><div class="rule-notice"><b>Uygulama notu</b><p>Miami öncesi cezalar ve DP’ler lig kararıyla sıfırlandı. Yeni puanlar 10 yarış sonra silinir. Madde 10.1 sıralama cezaları için “sonraki yarış”, Madde 16.2 “ilgili Grand Prix” diyor. Bu seans farkı kurulca açıklığa kavuşturulmalı; otomatik uygulama yapılmaz.</p></div><label class="search-field rule-search"><span>Kitapçıkta ara</span><input id="ruleSearch" type="search" value="${h(ruleQuery)}" placeholder="Örn. frenaj, DNF, 15.2…"></label><div class="rules-layout"><aside class="rule-index"><span class="eyebrow">İÇİNDEKİLER</span>${rules.map(r=>`<a class="${String(r.number)===value?'active':''}" href="#rules/${r.number}"><b>${String(r.number).padStart(2,'0')}</b>${h(r.title)}</a>`).join('')}</aside><section class="rule-articles">${visible.map(r=>`<details class="rule-article" id="rule-${r.number}" ${String(r.number)===value||query?'open':''}><summary><span> ${String(r.number).padStart(2,'0')}</span><h2>${h(r.title)}</h2><b>+</b></summary><div class="rule-body">${h(r.body)}</div></details>`).join('')||'<div class="empty">Aramanla eşleşen madde bulunamadı.</div>'}<p class="data-note">Metin FPL’nin F1 25 için uyarladığı lig yönetmeliğidir. Gerçek FIA’nın her ihlal için zorunlu kıldığı sabit bir ceza tablosu değildir. Süre ve grid miktarları kendiliğinden hesaplanmaz.</p></section></div>`;}

function gridTransferSummary(p){const transfer=L.pendingSanctions.find(t=>t.decisionIds.includes(p.id));return transfer&&transfer.decisionIds.length>1?`${h(p.name)} için ${transfer.decisionIds.length} kararın toplamı ${transfer.amount} sıradır. Bu kart toplamın bir parçasıdır; toplam ceza ayrıca eklenmez.`:'Bu grid cezası önceki zaman cezasının yerine geçer. Yeni bir süre veya grid cezası eklenmedi. Çekilmeyen grid için ek DP, ayrı R08 kaydında gösterilir.';}

let menuReturnFocus=null;
function navIcon(name){
 const paths={'pilot-cards':'<rect x="5" y="3" width="14" height="18" rx="2"/><circle cx="12" cy="9" r="2.5"/><path d="M8 16a4 4 0 0 1 8 0"/>',analysis:'<path d="M3 17 8 9l5 5 8-10M3 21h18"/>',statistics:'<path d="M4 20V10m8 10V4m8 16v-7M2 22h20"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',standings:'<path d="M8 21H3v-8h5zm7 0h-5V4h5zm7 0h-5V9h5z"/>',races:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h2m4 0h2"/>',teams:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',decisions:'<path d="M12 3 3 7v6c0 4 9 8 9 8s9-4 9-8V7Zm0 5v5m0 3h.01"/>',licence:'<rect x="3" y="5" width="18" height="15" rx="2"/><circle cx="8" cy="11" r="2"/><path d="M5 17a3 3 0 0 1 6 0m3-7h4m-4 4h4"/>',news:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M7 8h10M7 12h4m-4 4h4m4-4h2m-2 4h2"/>',rules:'<path d="M12 6c-3-3-8-3-10-1v15c3-2 7-2 10 0 3-2 7-2 10 0V5c-2-2-7-2-10 1Zm0 0v14"/>',menu:'<path d="M4 6h16M4 12h16M4 18h10"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
 return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.home}</svg>`;
}
function closeDetail(){const d=$('#detail');if(typeof d.close==='function')d.close();else d.removeAttribute('open');d.classList.remove('dialog-fallback');}
function setMenuOpen(open,restoreFocus=true){
 const menu=$('#mobile-menu'),backdrop=$('.mobile-menu-backdrop');if(!menu)return;
 if(open)menuReturnFocus=document.activeElement;
 menu.hidden=!open;if(backdrop)backdrop.hidden=!open;document.body.classList.toggle('menu-open',open);
 document.querySelectorAll('[data-menu-open]').forEach(b=>b.setAttribute('aria-expanded',String(open)));
 if(open)menu.querySelector('[data-menu-close]').focus();
 [$('#header'),$('#main'),$('#footer'),$('.mobile-tab-bar')].filter(Boolean).forEach(el=>{el.inert=open;if(open)el.setAttribute('aria-hidden','true');else el.removeAttribute('aria-hidden');});
 if(!open&&restoreFocus&&menuReturnFocus?.isConnected)menuReturnFocus.focus();
}
document.addEventListener('click',e=>{if(e.target.closest('[data-menu-open]'))setMenuOpen(true);if(e.target.closest('[data-menu-close]')||e.target.closest('#mobile-menu a[href]'))setMenuOpen(false);});
document.addEventListener('keydown',e=>{
 const menu=$('#mobile-menu');if(!menu||menu.hidden)return;
 if(e.key==='Escape'){e.preventDefault();setMenuOpen(false);return;}
 if(e.key==='Tab'){const nodes=Array.from(menu.querySelectorAll('a[href],button:not([disabled])'));const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===menu)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
window.addEventListener('resize',()=>{if(window.innerWidth>900)setMenuOpen(false,false);});

function msLabel(ms){if(ms==null)return '—';const min=Math.floor(ms/60000),sec=Math.floor(ms/1000)%60,milli=ms%1000;return (min?min+':':'')+String(sec).padStart(min?2:1,'0')+'.'+String(milli).padStart(3,'0');}
function classificationNotice(){if(!L.provisionalRounds?.includes(currentRound)||!['home','standings'].includes(route))return '';const race=gp(currentRound);return `<details class="classification-notice"><summary><span>!</span><div><b>${h(race.circuit.toLocaleUpperCase('tr'))} GP · GEÇİCİ KLASMAN</b><small>Geçici puanlar dâhil. Resmî sonuç bekleniyor.</small></div></summary><p>${h(race.classificationNote)}</p></details>`;}
function gridPolicyNotice(){return L.gridPolicy?`<aside class="classification-notice grid-policy-note"><b>18 KASIM 2026 · GÜNCEL GRİD UYGULAMASI</b><p>Lig yönetiminin yeni kararı: grid cezası alan pilotlar sondan başlar. Aşağıdaki kitapçıkta yer alan önceki sıra kademeleri tarihî metindir; güncel uygulama için bu duyuru esas alınır. Birden fazla cezalı pilotun kesin start sırası yönetimce belirlenecek.</p></aside>`:'';}

function signed(n){return n===null?'—':n>0?'+'+n:String(n);}
function gainBadge(n){return `<b class="gain-badge ${n>0?'positive':n<0?'negative':'neutral'}">${signed(n)}</b>`;}
function pilotPerformance(p){const total=performanceTotals({name:p.name})[0];if(!total)return '';return `<section class="panel pilot-performance"><div><p class="eyebrow">STARTTAN DAMALI BAYRAĞA · GRAND PRIX</p><h2>Rakamların arkasındaki yarış.</h2><p class="data-note">${total.comparable} finişte başlangıç sırası doğrulandı. Sprintler bu özete dahil değil.</p></div><div class="performance-numbers"><span><b>${signed(total.netGain)}</b>NET SIRA</span><span><b>${total.firstGrid}</b>İLK CEPTEN START</span><span><b>${total.fastestLaps}</b>EN HIZLI GP TURU</span></div>${link('statistics','Yarış yarış incele ↗','text-button',p.id)}</section>`;}
function statisticsPage(){
 const options={round:statsRound==='all'?null:Number(statsRound),session:statsSession,name:statsPilot==='all'?null:statsPilot};
 const rows=performanceRows(options),totals=performanceTotals(options),known=rows.filter(r=>r.observed);
 const biggest=rows.filter(r=>r.netGain>0).sort((a,b)=>b.netGain-a.netGain||b.round-a.round)[0];
 const fastest=totals.slice().sort((a,b)=>b.fastestLaps-a.fastestLaps)[0],first=totals.slice().sort((a,b)=>b.firstGrid-a.firstGrid)[0];
 const tied=(key,leader)=>leader?.[key]>0?totals.filter(t=>t[key]===leader[key]).map(t=>t.name).join(' / '):'Kayıt yok';
 const hero=(label,score,name,note,kind)=>`<article class="performance-hero ${kind}"><span class="eyebrow">${label}</span><strong>${score}</strong><h2>${h(name)}</h2><p>${h(note)}</p></article>`;
 const names=[...new Set(L.results.map(r=>r.name))].sort((a,b)=>a.localeCompare(b,'tr'));
 const scope=statsSession==='Sprint'?'Sprint':statsSession==='all'?'GP + Sprint':'Grand Prix';
 return heading('FPL 2026 · İSTATİSTİKLER','HER YARIŞ BİR İZ BIRAKIR.','Başlangıçtan lig klasmanına. Yükselişler, ilk cepten startlar ve en hızlı turlar.',`<a class="button secondary" href="assets/fpl-yaris-istatistikleri.csv" download>Tüm verileri indir · CSV ↓</a>`)+
 `<div class="metrics-coverage"><span><b>${raceMetrics.sessions.filter(s=>s.session==='Yarış'&&s.rows.length).length} / ${L.currentRound}</b> GP ekranı incelendi</span><span><b>${raceMetrics.sessions.filter(s=>s.session==='Sprint'&&s.rows.length).length} / ${new Set(L.results.filter(r=>r.session==='Sprint').map(r=>r.round)).size}</b> sprintte detay var</span><span>${h(L.asOf)} · ${h(new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'}).format(new Date(raceMetrics.reviewedAt+'T12:00:00Z')))}</span></div><div class="filters">${select('statsRound','Grand Prix',[['all','Tüm yarışlar'],...L.races.filter(r=>r.completed).map(r=>[r.round,r.name+' GP'])],statsRound)}${select('statsSession','Seans',[['Yarış','Grand Prix'],['Sprint','Sprint'],['all','GP + Sprint']],statsSession)}${select('statsPilot','Pilot',[['all','Tüm pilotlar'],...names.map(name=>[name,name+(pilot(name)?.active===false?' · Arşiv':'')])],statsPilot)}<span class="filter-count">${scope} · ${known.length} ekran eşleşmesi</span></div>`+
 `<section class="performance-highlights">${hero('EN BÜYÜK SIRA KAZANCI',biggest?'+'+biggest.netGain:'—',biggest?.name||'Karşılaştırılabilir finiş yok',biggest?`${biggest.gp} GP · ${biggest.session} · P${biggest.grid} → P${biggest.position}`:'Başlangıç ve resmî finiş birlikte gerekli.','gain')}${hero('EN HIZLI TUR BİRİNCİLİĞİ',fastest?.fastestLaps||'—',tied('fastestLaps',fastest),'Görselde mor işaretli seansın en iyi turu.','speed')}${hero('İLK CEPTEN START',first?.firstGrid||'—',tied('firstGrid',first),'GRID 1 kaydı · Sıralama pole sayısı değildir.','grid')}</section>`+
 `<section class="performance-method"><h2>Hangi rakam ne anlatıyor?</h2><div><p><b>Kazanılan sıra</b> = başlangıç − lig klasmanı. Cezalar, pitler ve yarış dışı kalan rakipler de etkiler. Gerçek atak sayısı değildir. Klasman dışı DNF, DNS ve DSQ için sıra kazancı hesaplanmaz.</p><p><b>Oyun → lig farkı</b>, ekranda görülen sonuçla lig klasmanı arasındaki değişimdir. Yalnız zaman cezasından kaynaklandığı varsayılmaz; durum düzeltmeleri de olabilir.</p><p><b>En hızlı tur birinciliği</b>, seansın en hızlı turunu alan pilotu sayar. Tur tur kayıt olmadığından hızlı tur sayısı, tempo, gerçek atak ve sıralama pole istatistiği çıkarılamaz.</p></div></section>`+
 `<section><div class="section-heading"><div><p class="eyebrow">${scope.toLocaleUpperCase('tr')} · SEÇİLİ KAPSAM</p><h2>Kim ne kadar ilerledi?</h2></div><span class="small muted">Toplam net sıraya göre · Kapsam sütununa dikkat</span></div><div class="panel table-scroll"><table class="standings-table"><thead><tr><th>PİLOT</th><th>NET SIRA</th><th>ÖLÇÜLEN FİNİŞ</th><th>İLK CEP</th><th>EN HIZLI TUR</th><th>EN İYİ YÜKSELİŞ</th></tr></thead><tbody>${totals.map(t=>`<tr><td>${driverLink(t.name)}${pilot(t.name)?.active===false?`<small class="metric-note">Arşiv · ${h(currentAffiliation(pilot(t.name)).name)}</small>`:''}</td><td>${t.comparable?gainBadge(t.netGain):'—'}</td><td>${t.comparable} finiş / ${t.startsKnown} start</td><td>${t.firstGrid}</td><td class="fastest-lap">${t.fastestLaps}</td><td>${t.bestGain?.netGain>0?gainBadge(t.bestGain.netGain)+' <small class="metric-note">'+h(t.bestGain.gp)+' · '+h(t.bestGain.session)+'</small>':'—'}</td></tr>`).join('')||'<tr><td colspan="6">Bu kapsam için ayrıntılı ekran kaydı yok.</td></tr>'}</tbody></table></div></section>`+
 `<section><div class="section-heading"><div><p class="eyebrow">İKİ KAYNAK. TEK KARŞILAŞTIRMA.</p><h2>Start → oyun → lig klasmanı.</h2></div><span class="small muted">Eksik veri — ile gösterilir.</span></div><div class="panel table-scroll metrics-detail"><table class="standings-table"><thead><tr><th>GP / PİLOT</th><th>START</th><th>OYUN EKRANI</th><th>LİG SONUCU</th><th>NET SIRA</th><th>OYUN → LİG</th><th>PİT</th><th>EN İYİ TUR</th></tr></thead><tbody>${rows.slice().sort((a,b)=>b.round-a.round||a.session.localeCompare(b.session)||(a.position??999)-(b.position??999)).map(r=>`<tr><td>${driverLink(r.name)}<small class="metric-note">${link('race',h(r.gp)+' · '+h(r.session),'text-button',String(r.round))}</small></td><td>${r.grid?'P'+r.grid:'—'}</td><td>${r.rawStatus?r.rawStatus==='FIN'?'P'+r.rawPosition:h(r.rawStatus):'—'}</td><td>${(r.status==='FIN'||r.classified)?r.position?'P'+r.position:h(r.positionLabel||'Finiş'):h(r.status)}</td><td>${gainBadge(r.netGain)}</td><td>${r.correction!==null?gainBadge(r.correction):r.rawStatus&&r.rawStatus!==r.status?'<small>Durum düzeltildi</small>':'—'}</td><td>${r.pitStops??'—'}</td><td class="${r.fastestLap?'fastest-lap':''}">${msLabel(r.bestLapMs)}${r.fastestLap?' <small>◆</small>':''}</td></tr>`).join('')}</tbody></table></div></section>`+
 `<details class="performance-sources"><summary>Veri kapsamı ve kaynaklar</summary><p>Geçici sonuçlar kanalındaki oyun ekranları başlangıç, pit ve kişisel en iyi tur için incelendi. Bitiş sırası, durum ve puanlar yayımlanmış lig klasmanlarından gelir. Avusturya sprint ve ana yarış gridleri ayrı telemetri oturumlarından. Ana yarışın geçici oyun klasmanı kayda gelmedi. Miami sprint ekranında başlangıç ve en iyi tur verisi yok. Bazı ekranlar tüm pilotları göstermiyor; görünmeyen satırlar tamamlanmadı. Ata, L The Justice, ahmet613448 ve yakisiklioyuncu nickleri kesin eşleşmediğinden pilot istatistiklerine bağlanmadı.</p><p>Galibiyetler ve puanlar önceki resmî kayıtlardan korunur. Ayrılan pilotların tarihî yarışları istatistik arşivinde görülebilir.</p><a class="text-button" href="https://discord.com/channels/1557757019434385538/1562538279608520877" target="_blank" rel="noopener noreferrer">Discord · Geçici oyun ekranları ↗</a><a class="text-button" href="https://discord.com/channels/1557757019434385538/1562538572500828350" target="_blank" rel="noopener noreferrer">Discord · Resmî sonuçlar ↗</a></details>`;
}

